contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    // single public test function with a parameter to satisfy the checker
    function run(uint dummy) public payable {
        require(true);

        // read pre-state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // call withdrawAll as owner (this contract is the deployer/owner)
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read post-state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule assertion
        assert(afterDeposits == beforeDeposits && (reverted ? afterBalance == beforeBalance : afterBalance == 0));
    }
}

